import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import type { Quote } from '../types';

// Singleton para a instância da IA
let aiInstance: GoogleGenAI | null = null;

// Imagens de fallback para quando a cota de imagem acabar ou não houver faturamento
const FALLBACK_IMAGES = [
  "https://images.unsplash.com/photo-1485846234645-a62644f84728?q=80&w=720&auto=format&fit=crop", // Cinema projector/Dark
  "https://images.unsplash.com/photo-1519681393784-d120267933ba?q=80&w=720&auto=format&fit=crop", // Mountains/Starry
  "https://images.unsplash.com/photo-1500462918059-b1a0cb512f1d?q=80&w=720&auto=format&fit=crop", // Red lights/Dark
  "https://images.unsplash.com/photo-1478760329108-5c3ed9d495a0?q=80&w=720&auto=format&fit=crop", // Dark clouds
  "https://images.unsplash.com/photo-1550684848-fac1c5b4e853?q=80&w=720&auto=format&fit=crop", // Dark mood
  "https://images.unsplash.com/photo-1534447677768-be436bb09401?q=80&w=720&auto=format&fit=crop"  // Black and white abstract
];

const getRandomFallbackImage = () => {
  return FALLBACK_IMAGES[Math.floor(Math.random() * FALLBACK_IMAGES.length)];
};

// Função para gerar IDs simples
const generateId = () => {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
};

// Função auxiliar para obter o cliente de forma segura
const getAiClient = () => {
  if (aiInstance) return aiInstance;

  if (!process.env.API_KEY) {
    console.error("API Key não encontrada. Verifique se API_KEY está definida.");
    throw new Error("API_KEY_MISSING");
  }

  aiInstance = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return aiInstance;
};

// Função de delay para backoff
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Wrapper para tentar novamente em caso de erro 503 (Overloaded)
async function withRetry<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const isOverloaded = 
      error?.message?.includes('overloaded') || 
      error?.message?.includes('503') || 
      error?.code === 503 ||
      error?.status === 'UNAVAILABLE';

    if (isOverloaded && retries > 0) {
      console.warn(`Modelo sobrecarregado. Tentando novamente em ${delay}ms... Restam ${retries} tentativas.`);
      await sleep(delay);
      return withRetry(operation, retries - 1, delay * 2); // Backoff exponencial
    }
    throw error;
  }
}

interface RawQuote {
  quote: string;
  author: string;
}

// Função auxiliar para limpar JSON que vem com markdown (```json ... ```)
const cleanJsonString = (str: string | undefined): string => {
  if (!str) return "{}";
  let cleaned = str.trim();
  if (cleaned.startsWith("```json")) {
    cleaned = cleaned.replace(/^```json/, "").replace(/```$/, "");
  } else if (cleaned.startsWith("```")) {
    cleaned = cleaned.replace(/^```/, "").replace(/```$/, "");
  }
  return cleaned.trim();
};

// ==========================================
// SERVIÇO PEXELS (FALLBACK)
// ==========================================
async function fetchPexelsImage(query: string): Promise<string | null> {
    const pexelsKey = process.env.PEXELS_API_KEY;

    if (!pexelsKey) {
        console.warn("Chave da API do Pexels não configurada. Pulando fallback Pexels.");
        return null;
    }

    try {
        console.log(`Buscando no Pexels por: ${query}`);
        const response = await fetch(`https://api.pexels.com/v1/search?query=${encodeURIComponent(query + " nature landscape")}&per_page=1&orientation=portrait&size=large`, {
            headers: {
                Authorization: pexelsKey
            }
        });

        if (!response.ok) {
            throw new Error(`Pexels API Error: ${response.status}`);
        }

        const data = await response.json();
        if (data.photos && data.photos.length > 0) {
            return data.photos[0].src.large2x;
        }
        return null;
    } catch (error) {
        console.error("Erro ao buscar imagem no Pexels:", error);
        return null;
    }
}

// ==========================================
// SERVIÇOS GEMINI (TEXTO)
// ==========================================

export async function getPhilosophicalQuotes(theme: string): Promise<Quote[]> {
  const ai = getAiClient();

  const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
    model: "gemini-2.5-flash", 
    contents: `Gere um array JSON contendo exatamente 3 citações filosóficas profundas e concisas sobre o tema '${theme}'.

    REGRAS OBRIGATÓRIAS:
    1. As citações devem estar EXCLUSIVAMENTE em PORTUGUÊS DO BRASIL (pt-BR). Não retorne em inglês ou outro idioma.
    2. Cada citação deve ser de um filósofo ou pensador renomado da história.
    3. Cada objeto no array deve ter as chaves "quote" e "author".`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
            type: Type.OBJECT,
            properties: {
              quote: {
                type: Type.STRING,
                description: "O texto da citação filosófica estritamente em Português do Brasil.",
              },
              author: {
                type: Type.STRING,
                description: "O nome do filósofo autor da citação.",
              },
            },
          required: ["quote", "author"],
        }
      },
    },
  }));

  const jsonString = cleanJsonString(response.text);
  if (!jsonString || jsonString === "{}") throw new Error("API retornou conteúdo vazio.");

  const quotesRaw: RawQuote[] = JSON.parse(jsonString);

  return quotesRaw.map(q => ({
      ...q,
      id: generateId(),
      imageUrl: ''
  }));
}

export async function getQuoteOfTheDay(): Promise<Quote> {
  const ai = getAiClient();

  const quoteResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
    model: "gemini-2.5-flash",
    contents: `Gere UMA, e apenas uma, citação filosófica em PORTUGUÊS DO BRASIL (pt-BR).

    REGRAS:
    1. Idioma: Português do Brasil apenas.
    2. A citação deve ser curta, profunda e inspiradora, sobre o tema 'sabedoria', 'natureza humana' ou 'resiliência'.
    3. Autor deve ser um filósofo renomado (ex: Sêneca, Marco Aurélio, Nietzsche, etc).
    4. A resposta deve ser apenas o JSON com texto e autor.`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          quote: { type: Type.STRING },
          author: { type: Type.STRING },
        },
        required: ["quote", "author"],
      },
    },
  }));

  const jsonString = cleanJsonString(quoteResponse.text);
  if (!jsonString || jsonString === "{}") throw new Error("API retornou conteúdo vazio para Citação do Dia.");

  const dailyQuoteRaw: RawQuote = JSON.parse(jsonString);
  const imageUrl = await generateQuoteImage(dailyQuoteRaw.quote);
  return { 
      ...dailyQuoteRaw, 
      id: generateId(),
      imageUrl 
  };
}

// ==========================================
// GERAÇÃO DE IMAGEM (AI + FALLBACK PEXELS)
// ==========================================

export async function generateQuoteImage(quoteText: string): Promise<string> {
    const ai = getAiClient();
    let searchKeywords = "abstract nature landscape";

    try {
        const promptAnalysisResponse = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: `Analyze this quote: "${quoteText}"

            Task:
            1. Create a "visual_prompt" for an AI Image Generator.
               - SUBJECT: Landscapes, nature, celestial bodies, or abstract concepts.
               - RULE 1: STRICTLY NO PEOPLE, NO HUMAN BEINGS, NO FACES, NO BODY PARTS.
               - RULE 2: Bright, clear, and elegant lighting. Avoid dark shadows or gloomy atmospheres.
               - RULE 3: Vertical composition for 9:16 mobile wallpaper.
               - STYLE: Ethereal, Cinematic, Photorealistic, 8k, High Dynamic Range.
               - STRICTLY NO TEXT, NO LETTERS.

            2. Create "search_keywords" for a stock photo site.
               - 3 keywords (nature, landscape, mood). NO PEOPLE keywords.

            Output JSON format only.`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        visual_prompt: { type: Type.STRING },
                        search_keywords: { type: Type.STRING }
                    }
                }
            }
        }));

        const analysisData = JSON.parse(cleanJsonString(promptAnalysisResponse.text));
        const visualPrompt = analysisData.visual_prompt;
        searchKeywords = (analysisData.search_keywords || "nature landscape") + " no people";

        // Passo 2: Tentar gerar imagem com Nano Banana
        const fullImagePrompt = `${visualPrompt}, Vertical 9:16 aspect ratio, mobile wallpaper, bright and clear lighting, vibrant colors, no humans, no people, sharp focus, HD, 8k resolution, highly detailed. NO TEXT.`;

        try {
            const response = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                  parts: [{ text: fullImagePrompt }]
                },
                config: {
                    // @ts-ignore
                    imageConfig: {
                        aspectRatio: "9:16",
                    }
                },
            }));

            let base64ImageBytes: string | null = null;
            if (response.candidates?.[0]?.content?.parts) {
              for (const part of response.candidates[0].content.parts) {
                if (part.inlineData && part.inlineData.data) {
                  base64ImageBytes = part.inlineData.data;
                  break;
                }
              }
            }

            if (base64ImageBytes) {
                return `data:image/jpeg;base64,${base64ImageBytes}`;
            }
            throw new Error("Dados de imagem não encontrados na resposta da IA.");

        } catch (aiError) {
            console.warn("Falha na geração IA. Tentando Pexels...", aiError);
            throw aiError;
        }

    } catch (error: any) {
        const pexelsImage = await fetchPexelsImage(searchKeywords);
        if (pexelsImage) {
            return pexelsImage;
        }
        return getRandomFallbackImage();
    }
}

import React, { useRef, useState, useEffect } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon } from './Icons';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ quote, isFavorite = false, onToggleFavorite }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [imgSrc, setImgSrc] = useState<string>('');
  const [isImageReady, setIsImageReady] = useState(false);

  useEffect(() => {
    let isMounted = true;
    setIsImageReady(false);

    const processImage = async () => {
      if (!quote.imageUrl) return;

      if (quote.imageUrl.startsWith('data:')) {
        if (isMounted) {
          setImgSrc(quote.imageUrl);
          setIsImageReady(true);
        }
        return;
      }

      try {
        const response = await fetch(quote.imageUrl, { mode: 'cors' });
        const blob = await response.blob();

        const reader = new FileReader();
        reader.onloadend = () => {
          if (isMounted) {
            setImgSrc(reader.result as string);
            setIsImageReady(true);
          }
        };
        reader.readAsDataURL(blob);
      } catch (error) {
        console.error("Erro ao converter imagem para download:", error);
        if (isMounted) {
          setImgSrc(quote.imageUrl);
          setIsImageReady(true);
        }
      }
    };

    processImage();

    return () => {
      isMounted = false;
    };
  }, [quote.imageUrl]);

  const handleDownload = async () => {
    if (!cardRef.current || !isImageReady) return;

    setIsDownloading(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 100));

      const canvas = await html2canvas(cardRef.current, {
        useCORS: true,
        allowTaint: false,
        scale: 3,
        backgroundColor: '#111827',
        logging: false,
        ignoreElements: (element) => element.classList.contains('exclude-from-capture'),
      });

      const image = canvas.toDataURL("image/jpeg", 0.95);

      const link = document.createElement('a');
      const safeAuthor = quote.author.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      link.download = `sophia-${safeAuthor}-${Date.now()}.jpg`;
      link.href = image;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    } catch (error) {
      console.error('Erro fatal no download:', error);
      alert('Não foi possível baixar a imagem devido a restrições do navegador. Tente tirar um print da tela.');
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div className="space-y-4">
      <div ref={cardRef} className="relative w-full aspect-[9/16] rounded-2xl overflow-hidden shadow-lg shadow-black/50 bg-gray-800 group">

        {/* Imagem de Fundo HD e Clara */}
        {imgSrc ? (
            <img 
                src={imgSrc} 
                alt={`Citação de ${quote.author}`} 
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-700 ${isImageReady ? 'opacity-100' : 'opacity-0'}`}
            />
        ) : null}

        {/* Skeleton / Loading State */}
        {!isImageReady && (
            <div className="absolute inset-0 bg-gray-800 animate-pulse flex items-center justify-center z-20">
                <span className="text-gray-500 text-sm font-medium">Semeando pensamentos...</span>
            </div>
        )}

        {/* Overlay Escuro Suavizado (Mais transparente para permitir imagens claras) */}
        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent z-0"></div>

        {/* Conteúdo de Texto */}
        <div className="absolute inset-0 flex flex-col justify-center items-center p-8 text-white text-center h-full z-10">
            <div className="flex-1 flex flex-col justify-center">
                <blockquote 
                    className="font-serif-display text-2xl sm:text-3xl md:text-4xl font-bold leading-snug tracking-wide"
                    style={{ textShadow: '2px 2px 10px rgba(0,0,0,0.8)' }}
                >
                    “{quote.quote}”
                </blockquote>
            </div>

            <div className="pb-12 w-full flex justify-end">
                <cite 
                    className="font-serif-display text-xl sm:text-2xl text-blue-100 not-italic border-t border-blue-400/50 pt-4 pl-8"
                    style={{ textShadow: '1px 1px 6px rgba(0,0,0,0.9)' }}
                >
                    — {quote.author}
                </cite>
            </div>
        </div>

        {/* Botão Favoritar */}
        {onToggleFavorite && (
            <button
                onClick={() => onToggleFavorite(quote)}
                className="exclude-from-capture absolute top-4 right-4 p-3 rounded-full bg-black/20 hover:bg-black/40 backdrop-blur-sm transition-all duration-300 z-20 group/heart"
                title={isFavorite ? "Remover dos Favoritos" : "Salvar nos Favoritos"}
            >
                <HeartIcon 
                    className={`w-6 h-6 transition-colors ${isFavorite ? 'text-red-500' : 'text-white group-hover/heart:text-red-300'}`} 
                    fill={isFavorite}
                />
            </button>
        )}

        {/* Watermark */}
        <div className="absolute bottom-3 left-0 right-0 text-center opacity-60 text-[10px] uppercase tracking-widest font-sans text-white z-10 font-bold" style={{ textShadow: '0 1px 2px rgba(0,0,0,0.5)' }}>
            Sophia • Biblioteca de Pensamentos
        </div>
      </div>

      <button
        onClick={handleDownload}
        disabled={isDownloading || !isImageReady}
        className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-gray-700 disabled:text-gray-500 text-white font-bold py-3.5 px-4 rounded-full flex items-center justify-center gap-2 transition-all duration-300 shadow-lg shadow-blue-900/20 active:scale-95"
      >
        {isDownloading ? (
            <span className="flex items-center gap-2">
                <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Revelando arte...
            </span>
        ) : (
            <>
                <DownloadIcon className="w-5 h-5" />
                Baixar Citação HD
            </>
        )}
      </button>
    </div>
  );
};

