import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";
import type { Quote } from '../types';

// Singleton para a instância da IA
let aiInstance: GoogleGenAI | null = null;

const FALLBACK_IMAGES = [
  "https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?q=80&w=1080&auto=format&fit=crop", // Mountains
  "https://images.unsplash.com/photo-1502082553048-f009c37129b9?q=80&w=1080&auto=format&fit=crop", // Forest/Minimalist
  "https://images.unsplash.com/photo-1497436072909-60f360e1d4b1?q=80&w=1080&auto=format&fit=crop", // Lake/Serene
  "https://images.unsplash.com/photo-1470770841072-f978cf4d019e?q=80&w=1080&auto=format&fit=crop", // Landscape
  "https://images.unsplash.com/photo-1518531933037-91b2f5f229cc?q=80&w=1080&auto=format&fit=crop"  // Nature detail
];

const getRandomFallbackImage = () => {
  return FALLBACK_IMAGES[Math.floor(Math.random() * FALLBACK_IMAGES.length)];
};

const generateId = () => {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
};

const getAiClient = () => {
  if (aiInstance) return aiInstance;
  if (!process.env.API_KEY) {
    throw new Error("API_KEY_MISSING");
  }
  aiInstance = new GoogleGenAI({ apiKey: process.env.API_KEY });
  return aiInstance;
};

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function withRetry<T>(operation: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await operation();
  } catch (error: any) {
    const isOverloaded = 
      error?.message?.includes('overloaded') || 
      error?.message?.includes('503') || 
      error?.code === 503 ||
      error?.status === 'UNAVAILABLE';

    if (isOverloaded && retries > 0) {
      await sleep(delay);
      return withRetry(operation, retries - 1, delay * 2);
    }
    throw error;
  }
}

interface RawQuote {
  quote: string;
  author: string;
}

const cleanJsonString = (str: string | undefined): string => {
  if (!str) return "{}";
  let cleaned = str.trim();
  if (cleaned.startsWith("```json")) {
    cleaned = cleaned.replace(/^```json/, "").replace(/```$/, "");
  } else if (cleaned.startsWith("```")) {
    cleaned = cleaned.replace(/^```/, "").replace(/```$/, "");
  }
  return cleaned.trim();
};

// ==========================================
// SERVIÇO PEXELS (FALLBACK ESTÉTICO)
// ==========================================
async function fetchPexelsImage(query: string, aestheticKeywords: string): Promise<string | null> {
    const pexelsKey = process.env.PEXELS_API_KEY;
    if (!pexelsKey) return null;

    try {
        // Combinando o tema da frase com palavras-chave de estilo para garantir qualidade no fallback
        const fullQuery = `${query} ${aestheticKeywords}`.trim();
        console.log(`Buscando Pexels Estético: ${fullQuery}`);

        const response = await fetch(`https://api.pexels.com/v1/search?query=${encodeURIComponent(fullQuery)}&per_page=1&orientation=portrait&size=large`, {
            headers: { Authorization: pexelsKey }
        });

        if (!response.ok) throw new Error(`Pexels API Error: ${response.status}`);

        const data = await response.json();
        if (data.photos && data.photos.length > 0) {
            return data.photos[0].src.large2x;
        }
        return null;
    } catch (error) {
        console.error("Erro no Pexels:", error);
        return null;
    }
}

