export async function generateQuoteImage(quoteText: string): Promise<string> {
    const ai = getAiClient();

    try {
        // Fase 1: Análise de Tema e Estilo
        const promptAnalysisResponse = await withRetry(() => ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: `Analise a citação: "${quoteText}"

            Tarefa:
            1. Crie um "visual_prompt" artístico para IA.
               - TEMA: Paisagens naturais, cosmos, ou formas abstratas que reflitam o significado da frase.
               - ESTILO PRIORITÁRIO: Cinematográfico, Minimalista, Fotorrealista ou Fotografia Artística de Alta Resolução. Aceitável Ilustração Realista se for elegante.
               - REGRAS CRÍTICAS: SEM PESSOAS, SEM ROSTOS, SEM TEXTO.
               - ILUMINAÇÃO: Clara, nítida, elegante, vibrante. Evite sombras pesadas ou tons fúnebres.

            2. Forneça "search_keywords" para banco de imagem caso a IA falhe.
               - Use termos em inglês como "nature landscape minimalist cinematic high quality".

            Output JSON only.`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        visual_prompt: { type: Type.STRING },
                        search_keywords: { type: Type.STRING }
                    }
                }
            }
        }));

        const analysisData = JSON.parse(cleanJsonString(promptAnalysisResponse.text));
        const visualPrompt = analysisData.visual_prompt;
        const searchKeywords = analysisData.search_keywords;

        // Fase 2: Geração via IA (Prioridade Máxima)
        const fullImagePrompt = `${visualPrompt}, vertical 9:16, masterpiece, 8k, cinematic lighting, minimalist composition, crisp details, photography or realistic illustration, vibrant but balanced colors, NO HUMANS, NO TEXT.`;

        try {
            const response = await withRetry(() => ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: { parts: [{ text: fullImagePrompt }] },
                config: {
                    // @ts-ignore
                    imageConfig: { aspectRatio: "9:16" }
                },
            }));

            let base64ImageBytes: string | null = null;
            if (response.candidates?.[0]?.content?.parts) {
              for (const part of response.candidates[0].content.parts) {
                if (part.inlineData?.data) {
                  base64ImageBytes = part.inlineData.data;
                  break;
                }
              }
            }

            if (base64ImageBytes) {
                return `data:image/jpeg;base64,${base64ImageBytes}`;
            }
            throw new Error("IA não retornou bytes.");

        } catch (aiError) {
            console.warn("IA falhou, recorrendo ao Pexels Estético.");
            // Fase 3: Fallback Pexels com reforço estético
            const pexelsImage = await fetchPexelsImage(searchKeywords, "minimalist cinematic photography nature no people");
            if (pexelsImage) return pexelsImage;
            throw aiError;
        }

    } catch (error) {
        return getRandomFallbackImage();
    }
}

