import React, { useRef, useState, useEffect } from 'react';
import type { Quote } from '../types';
import { DownloadIcon, HeartIcon, RefreshIcon, ShareIcon } from './Icons';
import html2canvas from 'html2canvas';

interface QuoteCardProps {
  quote: Quote;
  isFavorite?: boolean;
  onToggleFavorite?: (quote: Quote) => void;
  onRegenerateImage?: (quote: Quote) => Promise<void>;
}

export const QuoteCard: React.FC<QuoteCardProps> = ({ 
  quote, 
  isFavorite = false, 
  onToggleFavorite,
  onRegenerateImage 
}) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const [isDownloading, setIsDownloading] = useState(false);
  const [isSharing, setIsSharing] = useState(false);
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [imgSrc, setImgSrc] = useState<string>('');
  const [isImageReady, setIsImageReady] = useState(false);

  useEffect(() => {
    let isMounted = true;
    setIsImageReady(false);

    const processImage = async () => {
      if (!quote.imageUrl) return;

      if (quote.imageUrl.startsWith('data:')) {
        if (isMounted) {
          setImgSrc(quote.imageUrl);
          setIsImageReady(true);
        }
        return;
      }

      try {
        const response = await fetch(quote.imageUrl, { mode: 'cors' });
        const blob = await response.blob();

        const reader = new FileReader();
        reader.onloadend = () => {
          if (isMounted) {
            setImgSrc(reader.result as string);
            setIsImageReady(true);
          }
        };
        reader.readAsDataURL(blob);
      } catch (error) {
        console.error("Erro ao converter imagem para download:", error);
        if (isMounted) {
          setImgSrc(quote.imageUrl);
          setIsImageReady(true);
        }
      }
    };

    processImage();

    return () => {
      isMounted = false;
    };
  }, [quote.imageUrl]);

  const captureImage = async () => {
    if (!cardRef.current) return null;
    return await html2canvas(cardRef.current, {
      useCORS: true,
      allowTaint: false,
      scale: 3,
      backgroundColor: '#111827',
      logging: false,
      ignoreElements: (element) => element.classList.contains('exclude-from-capture'),
    });
  };

  const handleDownload = async () => {
    if (!cardRef.current || !isImageReady) return;

    setIsDownloading(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 100));
      const canvas = await captureImage();
      if (!canvas) return;

      const image = canvas.toDataURL("image/jpeg", 0.95);
      const link = document.createElement('a');
      const safeAuthor = quote.author.replace(/[^a-z0-9]/gi, '_').toLowerCase();
      link.download = `sophia-${safeAuthor}-${Date.now()}.jpg`;
      link.href = image;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error('Erro fatal no download:', error);
      alert('Não foi possível baixar a imagem devido a restrições do navegador.');
    } finally {
      setIsDownloading(false);
    }
  };

  const handleShare = async () => {
    if (!cardRef.current || !isImageReady) return;

    setIsSharing(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 100));
      const canvas = await captureImage();
      if (!canvas) return;

      const dataUrl = canvas.toDataURL("image/jpeg", 0.90);
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], `sophia-citacao-${Date.now()}.jpg`, { type: "image/jpeg" });

      if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: 'Sophia: Biblioteca de Pensamentos',
          text: `"${quote.quote}" — ${quote.author}`,
        });
      } else {
        try {
          await navigator.clipboard.writeText(`"${quote.quote}" — ${quote.author}\n\nEnviado via Sophia: Biblioteca de Pensamentos`);
          alert('Citação copiada para a área de transferência. A imagem será baixada para você compartilhar manualmente.');
          handleDownload();
        } catch (copyError) {
          handleDownload();
        }
      }
    } catch (error) {
      console.error('Erro ao compartilhar:', error);
      handleDownload();
    } finally {
      setIsSharing(false);
    }
  };

  const handleRegenerate = async () => {
    if (!onRegenerateImage || isRegenerating) return;

    setIsRegenerating(true);
    try {
      await onRegenerateImage(quote);
    } catch (error) {
      console.error("Erro ao regenerar imagem:", error);
    } finally {
      setIsRegenerating(false);
    }
  };

  return (
    <div className="space-y-4">
      <div ref={cardRef} className="relative w-full aspect-[9/16] rounded-2xl overflow-hidden shadow-lg shadow-black/50 bg-gray-800 group">

        {/* Imagem de Fundo com Ajustes de Brilho, Contraste e Vibração */}
        {imgSrc ? (
            <img 
                src={imgSrc} 
                alt={`Citação de ${quote.author}`} 
                className={`absolute inset-0 w-full h-full object-cover transition-all duration-700 brightness-[1.1] contrast-[1.05] saturate-[1.25] ${isImageReady ? 'opacity-100' : 'opacity-0'}`}
            />
        ) : null}

        {/* Skeleton / Loading State */}
        {(!isImageReady || isRegenerating) && (
            <div className="absolute inset-0 bg-gray-800/80 animate-pulse flex items-center justify-center z-20 backdrop-blur-sm">
                <div className="flex flex-col items-center gap-3">
                    <svg className="animate-spin h-8 w-8 text-blue-400" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    <span className="text-white text-sm font-medium tracking-wide">Cultivando nova arte...</span>
                </div>
            </div>
        )}

        {/* Overlay Escuro Estratégico para Legibilidade */}
        <div className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/15 to-black/5 z-0"></div>

        {/* Conteúdo de Texto com Sombra Reforçada */}
        <div className="absolute inset-0 flex flex-col justify-center items-center p-8 text-white text-center h-full z-10">
            <div className="flex-1 flex flex-col justify-center">
                <blockquote 
                    className="font-serif-display text-2xl sm:text-3xl md:text-4xl font-bold leading-snug tracking-wide"
                    style={{ textShadow: '0px 4px 12px rgba(0,0,0,0.9), 0px 2px 4px rgba(0,0,0,0.8)' }}
                >
                    “{quote.quote}”
                </blockquote>
            </div>

            <div className="pb-12 w-full flex justify-end">
                <cite 
                    className="font-serif-display text-xl sm:text-2xl text-blue-50 not-italic border-t border-white/20 pt-4 pl-8"
                    style={{ textShadow: '0px 2px 8px rgba(0,0,0,0.9)' }}
                >
                    — {quote.author}
                </cite>
            </div>
        </div>

        {/* Botão Favoritar */}
        {onToggleFavorite && (
            <button
                onClick={() => onToggleFavorite(quote)}
                className="exclude-from-capture absolute top-4 right-4 p-3 rounded-full bg-black/30 hover:bg-black/50 backdrop-blur-md transition-all duration-300 z-20 group/heart"
                title={isFavorite ? "Remover dos Favoritos" : "Salvar nos Favoritos"}
            >
                <HeartIcon 
                    className={`w-6 h-6 transition-colors ${isFavorite ? 'text-red-500' : 'text-white group-hover/heart:text-red-300'}`} 
                    fill={isFavorite}
                />
            </button>
        )}

        {/* Botão Trocar Imagem */}
        {onRegenerateImage && (
            <button
                onClick={handleRegenerate}
                disabled={isRegenerating || !isImageReady}
                className="exclude-from-capture absolute top-4 left-4 p-3 rounded-full bg-black/30 hover:bg-black/50 backdrop-blur-md transition-all duration-300 z-20 disabled:opacity-50"
                title="Tentar outra imagem"
            >
                <RefreshIcon className={`w-6 h-6 text-white ${isRegenerating ? 'animate-spin' : ''}`} />
            </button>
        )}

        {/* Watermark */}
        <div className="absolute bottom-3 left-0 right-0 text-center opacity-70 text-[10px] uppercase tracking-widest font-sans text-white z-10 font-bold" style={{ textShadow: '0 1px 4px rgba(0,0,0,0.8)' }}>
            Sophia • Biblioteca de Pensamentos
        </div>
      </div>

      <div className="flex flex-col gap-2">
        <div className="flex gap-2">
            <button
                onClick={handleShare}
                disabled={isSharing || !isImageReady || isRegenerating || isDownloading}
                className="flex-1 bg-white hover:bg-gray-100 text-gray-900 font-bold py-3.5 px-4 rounded-full flex items-center justify-center gap-2 transition-all duration-300 shadow-lg active:scale-95"
            >
                {isSharing ? (
                    <span className="flex items-center gap-2">
                        <svg className="animate-spin h-4 w-4 text-gray-900" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        Preparando...
                    </span>
                ) : (
                    <>
                        <ShareIcon className="w-5 h-5" />
                        Compartilhar
                    </>
                )}
            </button>

            <button
                onClick={handleRegenerate}
                disabled={isRegenerating || !isImageReady || isDownloading || isSharing}
                className="bg-gray-800 hover:bg-gray-700 disabled:bg-gray-700 disabled:text-gray-600 text-gray-300 font-bold py-3.5 px-6 rounded-full flex items-center justify-center transition-all duration-300 active:scale-95"
                title="Trocar Imagem"
            >
                <RefreshIcon className={`w-5 h-5 ${isRegenerating ? 'animate-spin' : ''}`} />
            </button>
        </div>

        <button
            onClick={handleDownload}
            disabled={isDownloading || !isImageReady || isRegenerating || isSharing}
            className="w-full bg-blue-600/20 hover:bg-blue-600/30 text-blue-300 font-semibold py-3 px-4 rounded-full flex items-center justify-center gap-2 transition-all duration-300 border border-blue-500/30 active:scale-95"
        >
            {isDownloading ? (
                <span className="flex items-center gap-2">
                    <svg className="animate-spin h-4 w-4 text-blue-300" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    Baixando...
                </span>
            ) : (
                <>
                    <DownloadIcon className="w-4 h-4" />
                    Salvar na Galeria
                </>
            )}
        </button>
      </div>
    </div>
  );
};
